<script setup lang="ts">import { computed,ref } from 'vue';import { useAppStore } from '@/stores/app';import { generatePassword,openVault,sealVault } from '@/services/crypto';import { id,now,type VaultEntry } from '@/domain/models';import { passwordStrength } from '@/domain/finance';import AppModal from '@/components/AppModal.vue';import UiIcon from '@/components/UiIcon.vue';const store=useAppStore();const password=ref('');const confirm=ref('');const entries=ref<VaultEntry[]>([]);const unlocked=ref(false);const error=ref('');const query=ref('');const reveal=ref(new Set<string>());const showAdd=ref(false);const service=ref('');const login=ref('');const entryPassword=ref('');const notes=ref('');const filtered=computed(()=>entries.value.filter(e=>`${e.service} ${e.login}`.toLowerCase().includes(query.value.toLowerCase())));const unlock=async()=>{error.value='';try{entries.value=store.data.vault?await openVault(store.data.vault,password.value):[];unlocked.value=true}catch{error.value='Nieprawidłowe hasło główne.'}};const create=async()=>{if(password.value!==confirm.value){error.value='Hasła nie są identyczne.';return}if(password.value.length<12){error.value='Hasło musi mieć co najmniej 12 znaków.';return}await store.setVault(await sealVault([],password.value));unlocked.value=true};const save=async()=>store.setVault(await sealVault(entries.value,password.value,store.data.vault?Uint8Array.from(atob(store.data.vault.salt),c=>c.charCodeAt(0)):undefined));const add=async()=>{const stamp=now();entries.value.push({id:id(),service:service.value,login:login.value,password:entryPassword.value,notes:notes.value,createdAt:stamp,updatedAt:stamp});await save();service.value='';login.value='';entryPassword.value='';notes.value='';showAdd.value=false};const remove=async(entryId:string)=>{entries.value=entries.value.filter(e=>e.id!==entryId);await save()};const toggle=(entryId:string)=>reveal.value.has(entryId)?reveal.value.delete(entryId):reveal.value.add(entryId);const copy=async(value:string)=>navigator.clipboard.writeText(value);const lock=()=>{entries.value=[];password.value='';unlocked.value=false;reveal.value.clear()}</script>
<template><section><div class="page-heading"><div><p class="kicker">SZYFROWANIE END-TO-END</p><h1>Bezpieczny sejf</h1><p>Hasła zaszyfrowane lokalnie algorytmem AES-256-GCM.</p></div><button v-if="unlocked" class="button secondary" @click="lock"><UiIcon name="Lock"/> Zablokuj</button></div><article v-if="!unlocked" class="unlock card"><span class="vault-lock"><UiIcon name="KeyRound" :size="34"/></span><h2>{{store.data.vault?'Odblokuj sejf':'Utwórz sejf'}}</h2><p>{{store.data.vault?'Wpisz hasło główne, aby odszyfrować dane.':'Ustaw silne hasło główne. Nie można go odzyskać.'}}</p><form class="form" @submit.prevent="store.data.vault?unlock():create()"><label>Hasło główne<div class="input-icon"><UiIcon name="LockKeyhole" :size="18"/><input v-model="password" required minlength="12" type="password" autocomplete="current-password"></div></label><label v-if="!store.data.vault">Powtórz hasło<input v-model="confirm" required minlength="12" type="password" autocomplete="new-password"></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="button primary full" type="submit">{{store.data.vault?'Odblokuj':'Utwórz i odblokuj'}}</button></form><small><UiIcon name="WifiOff" :size="14"/> Hasło nigdy nie opuszcza urządzenia</small></article><div v-else><div class="vault-toolbar"><label class="search"><UiIcon name="Search" :size="17"/><span class="sr-only">Szukaj wpisów</span><input v-model="query" placeholder="Szukaj serwisu lub loginu"></label><button class="button primary" @click="showAdd=true"><UiIcon name="Plus"/> Nowy wpis</button></div><div class="vault-grid"><article v-for="entry in filtered" :key="entry.id" class="card credential"><header><span class="service-icon">{{entry.service.slice(0,2).toUpperCase()}}</span><div><h2>{{entry.service}}</h2><p>{{entry.login}}</p></div><button class="icon-button danger" :aria-label="`Usuń ${entry.service}`" @click="remove(entry.id)"><UiIcon name="Trash2" :size="17"/></button></header><label>Hasło<div class="password-field"><code>{{reveal.has(entry.id)?entry.password:'••••••••••••••••'}}</code><button class="icon-button" :aria-label="reveal.has(entry.id)?'Ukryj hasło':'Pokaż hasło'" @click="toggle(entry.id)"><UiIcon :name="reveal.has(entry.id)?'EyeOff':'Eye'" :size="17"/></button><button class="icon-button" aria-label="Kopiuj hasło" @click="copy(entry.password)"><UiIcon name="Copy" :size="17"/></button></div></label><footer><span :class="`strength ${passwordStrength(entry.password)}`">{{passwordStrength(entry.password)}}</span><small>{{new Date(entry.updatedAt).toLocaleDateString('pl-PL')}}</small></footer></article><button class="new-credential" @click="showAdd=true"><UiIcon name="PlusCircle" :size="28"/><b>Dodaj pierwszy wpis</b><span>Dane zostaną zaszyfrowane</span></button></div></div><AppModal v-if="showAdd" title="Nowy wpis w sejfie" @close="showAdd=false"><form class="form" @submit.prevent="add"><label>Serwis<input v-model.trim="service" required autocomplete="off" placeholder="github.com"></label><label>Login<input v-model.trim="login" required autocomplete="off" placeholder="name@example.com"></label><label>Hasło<div class="generate-field"><input v-model="entryPassword" required autocomplete="new-password"><button class="button secondary" type="button" @click="entryPassword=generatePassword()">Generuj</button></div></label><label>Notatka<textarea v-model.trim="notes" maxlength="500"/></label><button class="button primary full" type="submit">Zaszyfruj i zapisz</button></form></AppModal></section></template>
